const $=s=>document.querySelector(s);
let map,currentQuery="",routeOverlays=[],shelterItems=[],facilityItems=[],infoWindow,places,geocoder;
const selected={origin:null,destination:null},selectionMarkers={origin:null,destination:null};
const escapeHtml=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
async function json(url){const r=await fetch(url),b=await r.json();if(!r.ok||b.error)throw new Error(b.error||"요청 실패");return b}
function loadKakao(key){return new Promise((resolve,reject)=>{const s=document.createElement("script");s.src=`https://dapi.kakao.com/v2/maps/sdk.js?appkey=${encodeURIComponent(key)}&autoload=false&libraries=services`;s.onload=()=>kakao.maps.load(resolve);s.onerror=()=>reject(new Error("카카오맵 SDK 로드 실패"));document.head.appendChild(s)})}
function routeQuery(){return new URLSearchParams({sx:selected.origin.longitude,sy:selected.origin.latitude,ex:selected.destination.longitude,ey:selected.destination.latitude}).toString()}
function markerImage(color,size=15){const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}"><circle cx="${size/2}" cy="${size/2}" r="${size/2-1}" fill="${color}" stroke="white" stroke-width="2"/></svg>`;return new kakao.maps.MarkerImage("data:image/svg+xml;charset=UTF-8,"+encodeURIComponent(svg),new kakao.maps.Size(size,size))}
function keywordSearch(query){return new Promise(resolve=>{places.keywordSearch(query,(data,status)=>resolve(status===kakao.maps.services.Status.OK?data:[]),{location:new kakao.maps.LatLng(35.18,129.05),radius:20000,sort:kakao.maps.services.SortBy.ACCURACY})})}
function addressSearch(query){return new Promise(resolve=>{geocoder.addressSearch(query,(data,status)=>resolve(status===kakao.maps.services.Status.OK?data:[]))})}
async function findPlaces(kind){const input=$(`#${kind}-search`),box=$(`#${kind}-results`),query=input.value.trim();if(query.length<2){box.innerHTML='<p class="empty-result">두 글자 이상 입력하세요.</p>';return}box.innerHTML='<p class="empty-result">검색 중…</p>';const [keywords,addresses]=await Promise.all([keywordSearch(query),addressSearch(query)]);const normalized=[...keywords.map(p=>({id:"p:"+p.id,name:p.place_name,address:p.road_address_name||p.address_name,longitude:Number(p.x),latitude:Number(p.y),category:p.category_name})),...addresses.map((p,i)=>({id:"a:"+i+":"+p.x+":"+p.y,name:p.road_address?.building_name||p.address_name,address:p.road_address?.address_name||p.address_name,longitude:Number(p.x),latitude:Number(p.y),category:"주소"}))];const unique=[...new Map(normalized.map(p=>[p.longitude+":"+p.latitude,p])).values()].slice(0,10);renderSearchResults(kind,unique)}
function renderSearchResults(kind,results){const box=$(`#${kind}-results`);box.innerHTML="";if(!results.length){box.innerHTML='<p class="empty-result">검색 결과가 없습니다.</p>';return}for(const place of results){const button=document.createElement("button");button.type="button";button.className="place-result";button.innerHTML=`<strong>${escapeHtml(place.name)}</strong><span>${escapeHtml(place.address)}</span><small>${escapeHtml(place.category)}</small>`;button.addEventListener("click",()=>selectPlace(kind,place));box.appendChild(button)}}
function selectPlace(kind,place){selected[kind]=place;$(`#${kind}-search`).value=place.name;$(`#${kind}-results`).innerHTML="";$(`#${kind}-selected`).innerHTML=`<strong>${escapeHtml(place.name)}</strong><br>${escapeHtml(place.address)}`;const position=new kakao.maps.LatLng(place.latitude,place.longitude);selectionMarkers[kind]?.setMap(null);selectionMarkers[kind]=new kakao.maps.Marker({map,position,image:markerImage(kind==="origin"?"#19a463":"#8b4bd8",22),title:place.name});map.panTo(position);$("#route-submit").disabled=!(selected.origin&&selected.destination);$("#status").textContent=selected.origin&&selected.destination?"출발지와 목적지가 선택됐습니다. 경로 검색을 누르세요.":"나머지 장소를 검색해 선택하세요."}
function showShelters(data){const icons={무더위쉼터:markerImage("#f26b38"),한파쉼터:markerImage("#2d8ee8")};infoWindow=new kakao.maps.InfoWindow({removable:true});for(const s of data.shelters){const marker=new kakao.maps.Marker({map,position:new kakao.maps.LatLng(s.latitude,s.longitude),image:icons[s.shelterType],title:s.name});kakao.maps.event.addListener(marker,"click",()=>{infoWindow.setContent(`<div class="shelter-info"><b>${escapeHtml(s.name)}</b><br>${escapeHtml(s.shelterType)}<br>${escapeHtml(s.address)}<br>좌표: ${s.latitude}, ${s.longitude}<br>data_index: ${s.dataIndex}<br>csv_row_number: ${s.csvRowNumber}<br>source_id: ${escapeHtml(s.sourceId)}</div>`);infoWindow.open(map,marker)});shelterItems.push({marker,type:s.shelterType})}updateShelters()}
function updateShelters(){const heat=$("#heat-toggle").checked,cold=$("#cold-toggle").checked;for(const x of shelterItems)x.marker.setMap((x.type==="무더위쉼터"?heat:cold)?map:null)}
function facilityDetails(f){const a=f.sourceAttributes??{};if(f.facilityType==="스마트 버스쉘터")return`설치연도: ${escapeHtml(a["설치년도"])}<br>부대시설: ${escapeHtml(a["부대시설 "])}`;return`설치장소: ${escapeHtml(a["설치장소설명"])}<br>평일: ${escapeHtml(a["평일운영시작시각"])}~${escapeHtml(a["평일운영종료시각"])}<br>토요일: ${escapeHtml(a["토요일운영시작시각"])}~${escapeHtml(a["토요일운영종료시각"])}<br>공휴일: ${escapeHtml(a["공휴일운영시작시각"])}~${escapeHtml(a["공휴일운영종료시각"])}<br>동시 사용: ${escapeHtml(a["동시사용가능대수"])}대 · 공기주입 ${escapeHtml(a["공기주입가능여부"])} · 휴대전화충전 ${escapeHtml(a["휴대전화충전가능여부"])}`}
function showFacilities(data){const images={"스마트 버스쉘터":markerImage("#7c4dff",17),"전동휠체어 급속충전기":markerImage("#00a58e",17),AED:markerImage("#e33d4f",18)},aedGroups=new Map();for(const f of data.facilities){if(f.facilityType==="AED"){const key=`${f.latitude},${f.longitude}`;if(!aedGroups.has(key))aedGroups.set(key,[]);aedGroups.get(key).push(f);continue}const marker=new kakao.maps.Marker({map,position:new kakao.maps.LatLng(f.latitude,f.longitude),image:images[f.facilityType],title:f.name});kakao.maps.event.addListener(marker,"click",()=>{infoWindow.setContent(`<div class="shelter-info"><b>${escapeHtml(f.name)}</b><br>${escapeHtml(f.facilityType)}<br>${escapeHtml(f.address)}<br>${facilityDetails(f)}<br>좌표: ${f.latitude}, ${f.longitude}<br>data_index: ${f.dataIndex}<br>csv_row_number: ${f.csvRowNumber}<br>source_id: ${f.sourceId===null?"없음":escapeHtml(f.sourceId)}${f.sourceKey?`<br>source_key: ${escapeHtml(f.sourceKey)}`:""}</div>`);infoWindow.open(map,marker)});facilityItems.push({marker,type:f.facilityType})}for(const group of aedGroups.values()){const first=group[0],marker=new kakao.maps.Marker({map,position:new kakao.maps.LatLng(first.latitude,first.longitude),image:images.AED,title:`AED ${group.length}개 · ${first.name}`});kakao.maps.event.addListener(marker,"click",()=>{const items=group.map(f=>`<li><b>${escapeHtml(f.name)}</b><br>source_id: ${escapeHtml(f.sourceId)} · data_index: ${f.dataIndex} · csv_row_number: ${f.csvRowNumber}<br>${escapeHtml(f.sourceAttributes?.["전화번호"]??"")}</li>`).join("");infoWindow.setContent(`<div class="shelter-info"><b>이 위치에 AED ${group.length}개</b><br>${escapeHtml(first.address)}<br>좌표: ${first.latitude}, ${first.longitude}<ol class="aed-list">${items}</ol></div>`);infoWindow.open(map,marker)});facilityItems.push({marker,type:"AED"})}updateFacilities()}
function updateFacilities(){const visible={"스마트 버스쉘터":$("#smart-bus-toggle").checked,"전동휠체어 급속충전기":$("#wheelchair-toggle").checked,AED:$("#aed-toggle").checked};for(const x of facilityItems)x.marker.setMap(visible[x.type]?map:null)}
function clearRoute(){for(const x of routeOverlays)x.setMap(null);routeOverlays=[]}
function line(points,options){const p=new kakao.maps.Polyline({map,path:points.map(x=>new kakao.maps.LatLng(x.latitude,x.longitude)),...options});routeOverlays.push(p)}
async function selectRoute(number,button,detailBox){document.querySelectorAll(".route").forEach(x=>x.classList.remove("active"));document.querySelectorAll(".route-detail").forEach(x=>{x.hidden=true;x.innerHTML=""});button.classList.add("active");detailBox.hidden=false;detailBox.innerHTML='<p class="detail-loading">상세 경로를 불러오는 중…</p>';$("#status").textContent=`${number}번 경로 형상 불러오는 중…`;try{const g=await json(`/api/routes/${number}/geometry?${currentQuery}`);clearRoute();const bounds=new kakao.maps.LatLngBounds();for(const l of g.transitLines){line(l.points,{strokeWeight:5,strokeColor:l.trafficClass===1?"#20a464":"#2468df",strokeOpacity:.88});l.points.forEach(p=>bounds.extend(new kakao.maps.LatLng(p.latitude,p.longitude)))}for(const l of g.walkingLines){line(l.points,{strokeWeight:4,strokeColor:"#ed7b2d",strokeOpacity:.9,strokeStyle:"shortdash"});l.points.forEach(p=>bounds.extend(new kakao.maps.LatLng(p.latitude,p.longitude)))}for(const s of g.stops){const m=new kakao.maps.Marker({map,position:new kakao.maps.LatLng(s.latitude,s.longitude),image:markerImage("#172033",10),title:s.name});routeOverlays.push(m)}map.setBounds(bounds);renderItinerary(g,detailBox);$("#status").textContent=`${number}번 경로: 대중교통 선 ${g.transitLines.length}개, 도보 구간 ${g.walkingLines.length}개`}catch(e){detailBox.innerHTML=`<p class="detail-error">${escapeHtml(e.message)}</p>`;$("#status").textContent=e.message}}
function renderItinerary(g,box){box.innerHTML="";for(const item of g.itinerary??[]){const step=document.createElement("article");step.className="journey-step "+item.mode;if(item.mode==="walk"){const indoor=item.geometryQuality==="indoor_station";step.innerHTML=`<div class="step-badge">${indoor?"환승":"도보"}</div><div><strong>${indoor?"역사 내부 환승":`도보 ${item.distanceM??0}m`}</strong><p>${indoor?"외부 도보 경로에서 제외":`${item.durationSec?Math.max(1,Math.round(item.durationSec/60)):item.durationMin??"-"}분 · ODsay 보행 경로`}</p></div>`}else{const options=(item.laneOptions??[]).map(x=>`${escapeHtml(x.name)}${x.direction?` · ${escapeHtml(x.direction)} 방면`:""}`).join(" / ");const stops=item.passStops??[],rideGuide=item.mode==="subway"?`${escapeHtml(item.startName)}${item.startExitNo?` ${escapeHtml(item.startExitNo)}번 출입구로 진입`:""} → ${escapeHtml(item.endName)} 하차${item.endExitNo?` · ${escapeHtml(item.endExitNo)}번 출구로 나가기`:""}`:`${escapeHtml(item.startName)} 승차 → ${escapeHtml(item.endName)} 하차`;step.innerHTML=`<div class="step-badge">${item.mode==="subway"?"지하철":"버스"}</div><div class="step-content"><strong>${options}</strong><p>${rideGuide} · 약 ${item.durationMin??"-"}분</p><details><summary>경유 지점 ${stops.length}개 보기</summary><ol>${stops.map(s=>`<li>${escapeHtml(s.name)}</li>`).join("")}</ol></details></div>`}box.appendChild(step)}}
function routeKind(route){const transit=route.segments.filter(s=>s.trafficType!==3),hasBus=transit.some(s=>s.trafficType===2),hasSubway=transit.some(s=>s.trafficType===1);return hasBus&&hasSubway?"mixed":hasSubway?"subway":"bus"}
function showRouteKind(kind){const tabs=[...document.querySelectorAll(".route-tab")],cards=[...document.querySelectorAll(".route-card")];for(const tab of tabs)tab.setAttribute("aria-selected",String(tab.dataset.routeKind===kind));for(const card of cards)card.hidden=kind!=="all"&&card.dataset.routeKind!==kind;const visible=cards.find(card=>!card.hidden);if(visible)visible.querySelector(".route")?.click();else clearRoute()}
function routeSignature(route){return route.segments.filter(s=>s.trafficType!==3).map(s=>`${s.trafficType}:${String(s.startName??"").trim()}>${String(s.endName??"").trim()}`).join("|")}
function groupRoutes(routes){const groups=new Map();for(const route of routes){const key=routeSignature(route);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(route)}return[...groups.values()].map(members=>{const representative=[...members].sort((a,b)=>(a.totalTimeMin??Infinity)-(b.totalTimeMin??Infinity))[0],transitCount=Math.max(...members.map(r=>r.segments.filter(s=>s.trafficType!==3).length)),modes=[];for(let i=0;i<transitCount;i++){const lines=new Set();for(const route of members){const segment=route.segments.filter(s=>s.trafficType!==3)[i];for(const name of segment?.lines??[])lines.add(name)}if(lines.size)modes.push([...lines].join(", "))}return{representative,members,modes}})}
function renderRoutes(data){const box=$("#routes"),tabs=$("#route-tabs"),groups=groupRoutes(data.routes),counts={all:groups.length,bus:0,subway:0,mixed:0};box.innerHTML="";for(const group of groups){const r=group.representative,card=document.createElement("article"),button=document.createElement("button"),detail=document.createElement("div"),kind=routeKind(r);counts[kind]++;card.className="route-card";card.dataset.routeKind=kind;button.className="route";detail.className="route-detail";detail.hidden=true;const alternativeText=group.members.length>1?` · 동일 구간 버스 대안 ${group.members.length}개`:"";button.innerHTML=`<strong>${r.routeNumber}번 · ${r.totalTimeMin}분</strong><small>도보 ${r.totalWalkM}m · 버스 환승 ${r.busTransitCount} · 지하철 환승 ${r.subwayTransitCount}${alternativeText}<br>${escapeHtml(group.modes.join(" → ")||r.firstStartStation+" → "+r.lastEndStation)}</small>`;button.onclick=()=>selectRoute(r.routeNumber,button,detail);card.append(button,detail);box.appendChild(card)}for(const tab of tabs.querySelectorAll(".route-tab")){const count=counts[tab.dataset.routeKind];tab.querySelector(".route-tab-count").textContent=count;tab.disabled=count===0;tab.onclick=()=>showRouteKind(tab.dataset.routeKind)}tabs.hidden=groups.length===0;$("#status").textContent=`ODsay 추천 ${data.routeCount}개 · 동일 구간을 묶어 ${groups.length}개로 표시`;if(groups.length)showRouteKind("all")}
async function searchRoutes(){if(!selected.origin||!selected.destination)return;currentQuery=routeQuery();$("#status").textContent="ODsay 경로 검색 중…";renderRoutes(await json("/api/routes?"+currentQuery))}
async function init(){try{const config=await json("/api/config");await loadKakao(config.kakaoJavaScriptKey);map=new kakao.maps.Map($("#map"),{center:new kakao.maps.LatLng(35.18,129.05),level:8});places=new kakao.maps.services.Places();geocoder=new kakao.maps.services.Geocoder();const [s,f]=await Promise.all([json("/api/shelters"),json("/api/facilities")]);showShelters(s);showFacilities(f);const smart=f.facilities.filter(x=>x.facilityType==="스마트 버스쉘터").length,wheelchair=f.facilities.filter(x=>x.facilityType==="전동휠체어 급속충전기").length,aeds=f.facilities.filter(x=>x.facilityType==="AED"),aedMarkers=new Set(aeds.map(x=>`${x.latitude},${x.longitude}`)).size;$("#status").textContent=`쉼터 ${s.count}개 · 스마트쉘터 ${smart}개 · 휠체어충전기 ${wheelchair}개 · AED ${aeds.length}개(${aedMarkers}개 위치)`}catch(e){$("#status").textContent=e.message}}
document.querySelectorAll("[data-search]").forEach(button=>button.addEventListener("click",()=>findPlaces(button.dataset.search).catch(e=>$("#status").textContent=e.message)));
["origin","destination"].forEach(kind=>$(`#${kind}-search`).addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();findPlaces(kind).catch(x=>$("#status").textContent=x.message)}}));
$("#route-form").addEventListener("submit",e=>{e.preventDefault();searchRoutes().catch(x=>$("#status").textContent=x.message)});
$("#heat-toggle").addEventListener("change",updateShelters);$("#cold-toggle").addEventListener("change",updateShelters);$("#smart-bus-toggle").addEventListener("change",updateFacilities);$("#wheelchair-toggle").addEventListener("change",updateFacilities);$("#aed-toggle").addEventListener("change",updateFacilities);init();
